// Bucket de reportes: política con un principal fijo y un rango de IP acotado, y Block Public Access completo.
export const configuracion = {
  blockPublicAccess: {
    account: { BlockPublicAcls: true, IgnorePublicAcls: true, BlockPublicPolicy: true, RestrictPublicBuckets: true },
    bucket: { BlockPublicAcls: true, IgnorePublicAcls: true, BlockPublicPolicy: true, RestrictPublicBuckets: true },
  },
  bucketPolicy: {
    Version: "2012-10-17",
    Statement: [
      {
        // Valor fijo de principal: esta sentencia no hace pública la política.
        Effect: "Allow",
        Principal: { AWS: "arn:aws:iam::111122223333:role/reportes" },
        Action: "s3:GetObject",
        Resource: "arn:aws:s3:::amzn-s3-demo-reportes/*",
      },
      {
        // Principal con comodín, pero limitado por un CIDR estrecho de aws:SourceIp: tampoco es pública.
        Effect: "Allow",
        Principal: "*",
        Action: "s3:GetObject",
        Resource: "arn:aws:s3:::amzn-s3-demo-reportes/*",
        Condition: { IpAddress: { "aws:SourceIp": "203.0.113.0/24" } },
      },
    ],
  },
  objectOwnership: "BucketOwnerEnforced",
};

