spec.code:
const objeto = { arn: "arn:aws:s3:::amzn-s3-demo-documentos/manual.pdf", accountId: "111122223333" };
const anonimo = { type: "anonymous" };
const resultado = aws.s3access.evaluateS3Access({ ...configuracion, request: { principal: anonimo, action: "s3:GetObject", resource: objeto } });
assert.strictEqual(resultado.allowed, false, "Una solicitud anónima no debe poder leer el objeto");

const objeto = { arn: "arn:aws:s3:::amzn-s3-demo-documentos/manual.pdf", accountId: "111122223333" };
const anonimo = { type: "anonymous" };
const resultado = aws.s3access.evaluateS3Access({ ...configuracion, request: { principal: anonimo, action: "s3:GetObject", resource: objeto } });
assert.strictEqual(resultado.isPublic, false, "El bucket no debe seguir siendo público");

const efectivo = aws.s3access.effectiveBlockPublicAccess(configuracion.blockPublicAccess);
assert.deepStrictEqual(efectivo, {
  BlockPublicAcls: true,
  IgnorePublicAcls: true,
  BlockPublicPolicy: true,
  RestrictPublicBuckets: true,
});

assert.deepStrictEqual(configuracion.bucketPolicy, {
  Version: "2012-10-17",
  Statement: [
    {
      Effect: "Allow",
      Principal: "*",
      Action: "s3:GetObject",
      Resource: "arn:aws:s3:::amzn-s3-demo-documentos/*",
    },
  ],
});
assert.strictEqual(configuracion.objectOwnership, "BucketOwnerEnforced");

const objeto = { arn: "arn:aws:s3:::amzn-s3-demo-documentos/manual.pdf", accountId: "111122223333" };
const anonimo = { type: "anonymous" };
const resultado = aws.s3access.evaluateS3Access({ ...configuracion, request: { principal: { type: "iam", arn: "arn:aws:iam::111122223333:role/auditoria", accountId: "111122223333" }, action: "s3:GetObject", resource: objeto } });
assert.strictEqual(resultado.allowed, true, "La cuenta propietaria debe seguir leyendo");

const objeto = { arn: "arn:aws:s3:::amzn-s3-demo-documentos/manual.pdf", accountId: "111122223333" };
const anonimo = { type: "anonymous" };
const resultado = aws.s3access.evaluateS3Access({ ...configuracion, request: { principal: { type: "iam", arn: "arn:aws:iam::222222222222:role/externo", accountId: "222222222222" }, action: "s3:GetObject", resource: objeto } });
assert.strictEqual(resultado.allowed, false, "El acceso entre cuentas derivado de una política pública debe bloquearse");

